/**
 * Vite inlines a `?inline` import as base64 regardless of file size; `astro/client.d.ts`
 * declares `*.woff` but not this variant. Used by `og/fonts.ts` to embed the fallback font in
 * its JS chunk, where an `import.meta.url` relative path does not resolve after bundling.
 */
declare module "*.woff?inline" {
  const dataUri: string;
  export default dataUri;
}

/** Virtual modules generated by `defineWalleConfig` (src/@walle/define-config.ts). */
declare module "virtual:walle-pwa" {
  const pwa: {
    enabled: boolean;
    manifestHref?: string;
    registerHref?: string;
    themeColor?: string | null;
    appleTouchIcon?: string | null;
  };
  export default pwa;
}

/**
 * Commerce UI gated at the module-graph level: `null` when `commerce.mode !== "shop"`,
 * so a site with commerce off never emits a chunk for the cart components.
 */
declare module "virtual:walle-features" {
  export const CartMount: typeof import("./commerce/CartMount.astro").default | null;
  export const CartBadge: typeof import("./commerce/CartBadge.astro").default | null;
}

/** One entry per configured `typography.fonts`, for Head.astro's `<Font cssVariable preload />`. */
declare module "virtual:walle-fonts" {
  export const fonts: Array<{
    cssVariable: string;
    preload: boolean | Array<{ weight?: string | number; style?: string; subset?: string }>;
  }>;
}

/** Palette and `typography.fonts` from theme.json, resolved at config time for OG rendering. */
declare module "virtual:walle-theme-data" {
  const data: {
    palette: Record<string, string>;
    fonts: Array<{
      name: string;
      provider: "local" | "google" | "fontsource";
      src?: string[];
      weights?: (string | number)[];
    }>;
  };
  export default data;
}

/**
 * One export per embeddable component, typed against its "standard" walle implementation: a
 * `components.<key>` override must accept the same props and slots.
 */
declare module "virtual:walle-components" {
  export const navbar: typeof import("./components/features/Navbar/Navbar.astro").default;
  export const footer: typeof import("./components/features/Footer.astro").default;
  export const card: typeof import("./components/features/Card/BasicCard.astro").default;
  export const breadcrumbs: typeof import("./components/features/Breadcrumbs.astro").default;
  export const pageHeader: typeof import("./components/features/Sections/HeaderStandard.astro").default;
  export const toc: typeof import("./components/features/Blog/BlogTableOfContents.astro").default;
}
